import{_ as a,o as t,c as n,a2 as i}from"./chunks/framework.CqGS6Fr9.js";const f=JSON.parse('{"title":"Your first session","description":"","frontmatter":{"pageId":"players/getting-started","contentRevision":5},"headers":[],"relativePath":"en/players/getting-started.md","filePath":"en/players/getting-started.md"}'),r={name:"en/players/getting-started.md"};function s(o,e,l,d,c,h){return t(),n("div",null,[...e[0]||(e[0]=[i('<h1 id="your-first-session" tabindex="-1">Your first session <a class="header-anchor" href="#your-first-session" aria-label="Permalink to &quot;Your first session&quot;">​</a></h1><p>Applies to: Rimlink 0.9.2 · RimWorld 1.7 · protocol 1.</p><h2 id="usage" tabindex="-1">Usage <a class="header-anchor" href="#usage" aria-label="Permalink to &quot;Usage {#usage}&quot;">​</a></h2><ol><li>Check the game version, install Harmony and Rimlink, enable them in the mod list and restart.</li><li>Open <strong>Multiplayer</strong>, add the server address and port, then authenticate using a method enabled by its administrator.</li><li>Verify a new certificate fingerprint through an independent channel. Resolve modpack differences.</li><li>Create a colony on the shared planet: the server controls world parameters; choose a free site.</li><li>Wait for colonists to arrive and play. Leave through the normal main-menu action and let saving/upload complete.</li><li>On the next login, confirm that this colony loads before starting transfers or travel.</li></ol><h2 id="first-evening" tabindex="-1">First evening: from server address to a second login <a class="header-anchor" href="#first-evening" aria-label="Permalink to &quot;First evening: from server address to a second login {#first-evening}&quot;">​</a></h2><p>Have the host/port, optional server password, DLC/mod requirements and an administrator contact for fingerprint verification ready. A server password gates the server; a personal password, where allowed, belongs to your account.</p><ol><li>Verify <strong>Multiplayer</strong> exists in the main menu. If absent, fix installation before networking.</li><li>Add the server, verify TLS and sign in. Finish modpack validation before creating a colony.</li><li>If the planet has not been initialized, wait for the administrator. Otherwise choose a scenario and a free tile on the server planet.</li><li>Once colonists arrive, pause and check the player name, home map and other settlements.</li><li>Use the normal return-to-menu action and let save/upload finish. Join the same server with the same account.</li><li>The same colony should load. Test this before trading or visiting, so the basic save path is known to work.</li></ol><p><strong>Outcome:</strong> one account, one settlement and a server save demonstrated by a second load. An unexpected new-colony screen is a reason to verify server/account, not create a replacement.</p><h2 id="first-failure" tabindex="-1">If the first login does not finish <a class="header-anchor" href="#first-failure" aria-label="Permalink to &quot;If the first login does not finish {#first-failure}&quot;">​</a></h2><p>Separate stages: missing menu means installation; no response means address/port/reachability; changed pin means security; mismatch means collection; login refusal means account; load failure means save/dependencies. Record the exact message and stage. Do not create another account to “recover” goods after a drop.</p><p>For a first safe exchange, use a small quantity of an ordinary resource and check both mailboxes. This is not a load test or a reason to send valuable colonists before validating the collection.</p><h2 id="limits" tabindex="-1">Limits and safety <a class="header-anchor" href="#limits" aria-label="Permalink to &quot;Limits and safety {#limits}&quot;">​</a></h2><p>Do not force-kill the process during upload. An initial administrator login may create the world; ordinary players must not bypass it by creating a separate planet.</p><h2 id="related" tabindex="-1">See also <a class="header-anchor" href="#related" aria-label="Permalink to &quot;See also {#related}&quot;">​</a></h2><ul><li><a href="./install">Installing the mod</a></li><li><a href="./connect">Connecting and signing in</a></li><li><a href="./saves-recovery">Saves and recovery</a></li></ul>',15)])])}const p=a(r,[["render",s]]);export{f as __pageData,p as default};
